//! Shared deterministic scene-noise and display transforms for cinematic
//! geometry examples. These are host-side shading utilities; geodesic state
//! and backend-neutral graph kernels stay in `axgeom`.

/// Linear-RGB equirectangular environment sampled after geodesic transport.
///
/// Procedural skies are stationary functions on the sphere. Baking that function once avoids
/// reevaluating its noise octaves for every escaped ray on every animated frame. The atlas is
/// generated by disjoint row bands, so initialization scales across host cores without locks or
/// unsafe pointer publication.
pub struct SkyTexture {
    pub width: usize,
    pub height: usize,
    texels: Vec<[f32; 3]>,
}

impl SkyTexture {
    pub fn new(width: usize, height: usize, texels: Vec<[f32; 3]>) -> Self {
        assert!(width > 0 && height > 0);
        assert_eq!(texels.len(), width * height);
        Self {
            width,
            height,
            texels,
        }
    }

    pub fn generate(
        width: usize,
        height: usize,
        threads: usize,
        shader: impl Fn([f32; 3]) -> [f32; 3] + Sync,
    ) -> Self {
        assert!(width > 0 && height > 0 && threads > 0);
        let mut texels = vec![[0.0; 3]; width * height];
        let workers = threads.min(height);
        let rows_per_band = height.div_ceil(workers);
        let texels_per_band = rows_per_band * width;
        std::thread::scope(|scope| {
            for (band, rows) in texels.chunks_mut(texels_per_band).enumerate() {
                let first_row = band * rows_per_band;
                let shader = &shader;
                scope.spawn(move || {
                    for (offset, texel) in rows.iter_mut().enumerate() {
                        let x = offset % width;
                        let y = first_row + offset / width;
                        let longitude =
                            ((x as f32 + 0.5) / width as f32 - 0.5) * core::f32::consts::TAU;
                        let latitude =
                            (0.5 - (y as f32 + 0.5) / height as f32) * core::f32::consts::PI;
                        let (sin_longitude, cos_longitude) = longitude.sin_cos();
                        let (sin_latitude, cos_latitude) = latitude.sin_cos();
                        *texel = shader([
                            cos_longitude * cos_latitude,
                            sin_longitude * cos_latitude,
                            sin_latitude,
                        ]);
                    }
                });
            }
        });
        Self::new(width, height, texels)
    }

    #[inline]
    pub fn sample_equirectangular(&self, direction: [f32; 3]) -> [f32; 3] {
        let u = direction[1].atan2(direction[0]) * (0.5 / core::f32::consts::PI) + 0.5;
        let v = direction[2].clamp(-1.0, 1.0).acos() / core::f32::consts::PI;
        self.sample_equirectangular_uv(u, v)
    }

    /// Sample preprojected equirectangular coordinates. Longitude wraps;
    /// latitude clamps at the poles.
    #[inline]
    pub fn sample_equirectangular_uv(&self, u: f32, v: f32) -> [f32; 3] {
        let x = u * self.width as f32 - 0.5;
        let y = v * self.height as f32 - 0.5;
        let x0 = x.floor() as i32;
        let y0 = y.floor() as i32;
        let x_amount = x - x0 as f32;
        let y_amount = y - y0 as f32;
        let index = |x: i32, y: i32| {
            let x = x.rem_euclid(self.width as i32) as usize;
            let y = y.clamp(0, self.height as i32 - 1) as usize;
            self.texels[x + self.width * y]
        };
        let low = index(x0, y0);
        let right = index(x0 + 1, y0);
        let down = index(x0, y0 + 1);
        let down_right = index(x0 + 1, y0 + 1);
        core::array::from_fn(|channel| {
            let upper = low[channel] + x_amount * (right[channel] - low[channel]);
            let lower = down[channel] + x_amount * (down_right[channel] - down[channel]);
            upper + y_amount * (lower - upper)
        })
    }
}

#[inline]
pub fn hash_u32(mut value: u32) -> u32 {
    value ^= value >> 16;
    value = value.wrapping_mul(0x7feb_352d);
    value ^= value >> 15;
    value = value.wrapping_mul(0x846c_a68b);
    value ^ (value >> 16)
}

fn value_noise(x: f32, y: f32, seed: u32) -> f32 {
    let x0 = x.floor() as i32;
    let y0 = y.floor() as i32;
    let tx = x - x0 as f32;
    let ty = y - y0 as f32;
    let smooth = |value: f32| value * value * (3.0 - 2.0 * value);
    let sample = |dx: i32, dy: i32| {
        hash_u32(
            (x0.wrapping_add(dx) as u32).wrapping_mul(0x9e37_79b9)
                ^ (y0.wrapping_add(dy) as u32).wrapping_mul(0x85eb_ca6b)
                ^ seed,
        ) as f32
            / u32::MAX as f32
    };
    let sx = smooth(tx);
    let sy = smooth(ty);
    let low = sample(0, 0) + sx * (sample(1, 0) - sample(0, 0));
    let high = sample(0, 1) + sx * (sample(1, 1) - sample(0, 1));
    low + sy * (high - low)
}

/// Five-octave, rotated value-noise sum in `[0, 1]`.
pub fn fbm(mut x: f32, mut y: f32, seed: u32) -> f32 {
    let mut sum = 0.0;
    let mut weight = 0.5;
    let mut normalization = 0.0;
    for octave in 0_u32..5 {
        sum += weight * value_noise(x, y, seed.wrapping_add(octave * 0x27d4_eb2d));
        normalization += weight;
        let next_x = 1.73 * x - 1.11 * y + 7.3;
        y = 1.11 * x + 1.73 * y - 4.1;
        x = next_x;
        weight *= 0.5;
    }
    sum / normalization
}

/// ACES fitted tone mapping followed by the sRGB transfer function.
pub fn pack_aces(color: [f32; 3]) -> u32 {
    let encode = |linear: f32| {
        let linear = linear.max(0.0);
        let mapped = ((linear * (2.51 * linear + 0.03)) / (linear * (2.43 * linear + 0.59) + 0.14))
            .clamp(0.0, 1.0);
        let srgb = if mapped <= 0.003_130_8 {
            12.92 * mapped
        } else {
            1.055 * mapped.powf(1.0 / 2.4) - 0.055
        };
        (srgb * 255.0 + 0.5) as u32
    };
    0xff00_0000 | (encode(color[0]) << 16) | (encode(color[1]) << 8) | encode(color[2])
}
